import sys

def hamming_weight_brute(n: int) -> int:
    return bin(n).count('1')

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(hamming_weight_brute(n))

import sys

def hamming_weight_opt(n: int) -> int:
    cnt = 0
    while n:
        cnt += n & 1
        n >>= 1
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(hamming_weight_opt(n))

import sys

def hamming_weight_best(n: int) -> int:
    cnt = 0
    while n:
        n &= n - 1
        cnt += 1
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(hamming_weight_best(n))
